private void btnHesapla_Click(object sender, EventArgs e)
{
    try
    {
        double saat = Convert.ToDouble(txtSaat.Text);
        double ucret = 0;
        string tarifeAdi = "";

        if (saat <= 0)
        {
            MessageBox.Show("Lütfen 0'dan büyük bir süre giriniz!");
            return;
        }
        else if (saat <= 1)
        {
            ucret = 40; tarifeAdi = "Kısa Süreli Park";
        }
        else if (saat <= 4)
        {
            ucret = 90; tarifeAdi = "Standart Park";
        }
        else if (saat <= 8)
        {
            ucret = 160; tarifeAdi = "Uzun Süreli Park";
        }
        else
        {
            double fazla = saat - 8;
            ucret = 160 + (fazla * 25);
            tarifeAdi = "Gün Boyu Park (Ek Saatli)";
        }
        lblTarife.Text = "Tarife: " + tarifeAdi;
        lblUcret.Text = "Ödenecek: " + ucret.ToString("0.00") + " TL";
    }
    catch { MessageBox.Show("Lütfen geçerli bir saat giriniz!"); }
}

